/**
 * Discord Rich Presence for OpenCode v2.
 *
 * 狀態全部來自事件流，不用 V1 的 chat.message / chat.params / tool.execute.* hooks。
 * 只訂閱會改變 presence 的事件，text delta 這種高頻事件不碰。
 *
 * V2 每個 location 各跑一次 setup（同一個 process）。Discord 只接受一條
 * IPC 連線，所以 client 和狀態放在 globalThis 共用，最後一個 setup 收攤時才斷線。
 */
import { DiscordRPCClient } from "./discord.js";
import { getConfig } from "./config.js";
const EVENTS = [
    "session.created",
    "session.deleted",
    "session.idle",
    "session.model.selected",
    "session.execution.started",
    "session.execution.succeeded",
    "session.execution.failed",
    "session.execution.interrupted",
    "session.step.started",
    "session.tool.called",
    "session.tool.success",
    "session.tool.failed",
    "permission.asked",
    "permission.replied",
    "form.created",
    "form.replied",
    "form.cancelled",
];
const SHARED = Symbol.for("opencode-discord-rpc.shared.v2");
/** Discord 有 rate limit，同一時間只留一個 writer，狀態合併後再送。 */
const SEND_DELAY = 1000;
function signature(config) {
    return `${config.clientId}|${config.retryInterval}|${config.maxRetries}|${config.enabled}`;
}
function settle(shared) {
    if (shared.busy.size === 0) {
        return shared.activeSession ? "waiting" : "idle";
    }
    let latest;
    for (const entry of shared.busy.values()) {
        if (!latest || entry.at >= latest.at)
            latest = entry;
    }
    return latest.status;
}
async function flush(shared) {
    if (shared.writing)
        return;
    shared.writing = true;
    try {
        while (shared.dirty) {
            shared.dirty = false;
            const status = settle(shared);
            const key = `${status}|${shared.model ?? ""}`;
            if (key === shared.lastSent)
                continue;
            shared.lastSent = key;
            await shared.rpc.updatePresence({
                status,
                modelName: shared.model ?? undefined,
            });
        }
    }
    finally {
        shared.writing = false;
    }
}
function schedule(shared) {
    shared.dirty = true;
    if (shared.timer || shared.writing)
        return;
    shared.timer = setTimeout(() => {
        shared.timer = null;
        void flush(shared);
    }, SEND_DELAY);
    shared.timer.unref?.();
}
function acquire(config, log) {
    const store = globalThis;
    const key = signature(config);
    const existing = store[SHARED];
    if (existing && existing.signature === key) {
        existing.refs++;
        return { shared: existing, owner: false };
    }
    // 設定或外掛版本換了：舊的由它自己的 refs 收掉，不要沿用
    const rpc = new DiscordRPCClient(config, log);
    const shared = {
        refs: 1,
        signature: key,
        rpc,
        ready: rpc.connect(),
        busy: new Map(),
        roots: new Map(),
        activeSession: null,
        model: null,
        lastSent: "",
        dirty: false,
        writing: false,
        timer: null,
    };
    store[SHARED] = shared;
    return { shared, owner: true };
}
function release(shared) {
    if (shared.timer) {
        clearTimeout(shared.timer);
        shared.timer = null;
    }
    shared.dirty = false;
    shared.refs--;
    if (shared.refs > 0)
        return;
    const store = globalThis;
    if (store[SHARED] === shared)
        delete store[SHARED];
    return shared.rpc.disconnect();
}
/**
 * Extract model display name from model ID
 * e.g., "gpt-4o-2024-08-06" -> "gpt-4o"
 * e.g., "claude-sonnet-4-20250514" -> "claude-sonnet-4"
 */
function formatModelName(modelId) {
    if (!modelId)
        return "OpenCode";
    return modelId.replace(/-\d{4}-\d{2}-\d{2}$/, "").replace(/-\d{8}$/, "");
}
const plugin = {
    id: "opencode-discord-rpc",
    async setup(ctx) {
        const config = getConfig(ctx.options);
        const log = (message, level = "info") => {
            const line = `[discord-rpc] ${message}`;
            if (level === "error")
                console.error(line);
            else if (level === "warn")
                console.warn(line);
            else
                console.log(line);
        };
        if (!config.enabled) {
            log("Plugin disabled via configuration");
            return;
        }
        const { shared, owner } = acquire(config, log);
        const controller = new AbortController();
        const isRoot = async (sessionID) => {
            const cached = shared.roots.get(sessionID);
            if (cached !== undefined)
                return cached;
            try {
                const session = await ctx.session.get({ sessionID });
                const root = !session.parentID;
                shared.roots.set(sessionID, root);
                return root;
            }
            catch {
                // 查不到就不要用它蓋掉目前顯示的 model
                shared.roots.set(sessionID, false);
                return false;
            }
        };
        if (owner) {
            log("Initializing Discord Rich Presence...", "info");
            shared.rpc.startSession();
            schedule(shared);
        }
        const sleep = (ms) => new Promise((resolve) => {
            const timer = setTimeout(resolve, ms);
            timer.unref?.();
            controller.signal.addEventListener("abort", () => {
                clearTimeout(timer);
                resolve();
            }, { once: true });
        });
        const run = async () => {
            while (!controller.signal.aborted) {
                try {
                    for await (const event of ctx.event.subscribe({
                        types: [...EVENTS],
                        signal: controller.signal,
                    })) {
                        switch (event.type) {
                            case "session.created": {
                                const parentID = event.data.parentID;
                                shared.roots.set(event.data.sessionID, !parentID);
                                // subagent 不重置計時，否則每個子任務都會把 elapsed 歸零
                                if (!parentID) {
                                    shared.activeSession = event.data.sessionID;
                                    shared.rpc.startSession();
                                }
                                // 只開新 session 還沒送訊息，這裡不放 busy，否則會卡在 Coding
                                break;
                            }
                            case "session.deleted": {
                                shared.busy.delete(event.data.sessionID);
                                shared.roots.delete(event.data.sessionID);
                                if (event.data.sessionID === shared.activeSession) {
                                    shared.activeSession = null;
                                }
                                break;
                            }
                            case "session.execution.started": {
                                shared.busy.set(event.data.sessionID, {
                                    status: "coding",
                                    at: Date.now(),
                                });
                                // 外掛載入前就存在的 session 收不到 session.created，從這裡補
                                if (await isRoot(event.data.sessionID)) {
                                    shared.activeSession = event.data.sessionID;
                                }
                                break;
                            }
                            case "session.execution.succeeded":
                            case "session.execution.failed":
                            case "session.execution.interrupted":
                            case "session.idle": {
                                shared.busy.delete(event.data.sessionID);
                                break;
                            }
                            case "session.step.started": {
                                shared.busy.set(event.data.sessionID, {
                                    status: "thinking",
                                    at: Date.now(),
                                });
                                if (event.data.model && (await isRoot(event.data.sessionID))) {
                                    shared.model = formatModelName(event.data.model.id);
                                }
                                break;
                            }
                            case "session.model.selected": {
                                if (await isRoot(event.data.sessionID)) {
                                    shared.model = formatModelName(event.data.model.id);
                                }
                                break;
                            }
                            case "session.tool.called": {
                                shared.busy.set(event.data.sessionID, {
                                    status: "coding",
                                    at: Date.now(),
                                });
                                break;
                            }
                            case "session.tool.success":
                            case "session.tool.failed": {
                                shared.busy.set(event.data.sessionID, {
                                    status: "thinking",
                                    at: Date.now(),
                                });
                                break;
                            }
                            // 等使用者批准或回答時，這個 session 不在動了
                            case "permission.asked": {
                                shared.busy.delete(event.data.sessionID);
                                break;
                            }
                            case "form.created": {
                                shared.busy.delete(event.data.form.sessionID);
                                break;
                            }
                            // 批准或關掉之後工作繼續跑
                            case "permission.replied":
                            case "form.replied":
                            case "form.cancelled": {
                                shared.busy.set(event.data.sessionID, {
                                    status: "coding",
                                    at: Date.now(),
                                });
                                break;
                            }
                        }
                        schedule(shared);
                    }
                    return;
                }
                catch (error) {
                    if (controller.signal.aborted)
                        return;
                    // 不清共用狀態：其他 location 的訂閱還在正常收事件
                    log(`Event stream failed, reconnecting: ${error instanceof Error ? error.message : String(error)}`, "warn");
                    await sleep(2000);
                }
            }
        };
        void run();
        return async () => {
            controller.abort();
            await release(shared);
        };
    },
};
// Default export for OpenCode
export default plugin;
// Re-export config utilities for users who want to check configuration
export { getConfig } from "./config.js";
